212	// The structural invariant the whole regression rests on: above the retained
213	// h1, the reorg changes timestamps only. Every height, hash, parent link and
214	// ordered transaction list is identical on the two chains, the tip stays 5,
215	// and at least one block actually moves across each window boundary.
216	func TestReorgTimeWindowFixtureKeepsStructureMovesTimesOnly(t *testing.T) {
217		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
218		if len(oldChain) != len(newChain) || len(oldChain) != 5 {
219			t.Fatalf("chain lengths old=%d new=%d, want 5/5", len(oldChain), len(newChain))
220		}
221		for i := range oldChain {
222			o, n := oldChain[i], newChain[i]
223			if o.Height != n.Height || o.Hash != n.Hash || o.Parent != n.Parent {
224				t.Fatalf("height %d identity changed: old={%d %s %s} new={%d %s %s}",
225					i+1, o.Height, o.Hash, o.Parent, n.Height, n.Hash, n.Parent)
226			}
227			if !reflect.DeepEqual(o.Txs, n.Txs) {
228				t.Fatalf("height %d transaction list changed: old=%v new=%v", o.Height, o.Txs, n.Txs)
229			}
230		}
231		// Per-height transition table, including the unchanged real-zero h1 and the
232		// missing->known h4.
233		flips := map[int64]struct {
234			oldIn, newIn bool
235			oldTime      *int64
236			newTime      *int64
237		}{
238			1: {true, true, intptr(0), intptr(0)},
239			2: {true, false, intptr(105), intptr(120)},
240			3: {false, true, intptr(110), intptr(100)},
241			4: {false, true, nil, intptr(105)},
242			5: {true, true, intptr(108), intptr(102)},
243		}
244		movedOut, movedIn := 0, 0
245		for height, want := range flips {
246			o, n := oldChain[height-1].Time, newChain[height-1].Time
247			if !sameIntptr(o, want.oldTime) || !sameIntptr(n, want.newTime) {
248				t.Fatalf("height %d times old=%v new=%v, want %v/%v", height, o, n, want.oldTime, want.newTime)
249			}
250			gotOld := timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}.contains(o)
251			gotNew := timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}.contains(n)
252			if gotOld != want.oldIn || gotNew != want.newIn {
253				t.Fatalf("height %d window membership old=%v(want %v) new=%v(want %v)",
254					height, gotOld, want.oldIn, gotNew, want.newIn)
255			}
256			if want.oldIn && !want.newIn {
257				movedOut++
258			}
259			if !want.oldIn && want.newIn {
260				movedIn++
261			}
262		}
263		if movedOut != 1 || movedIn != 2 {
264			t.Fatalf("boundary crossings: movedOut=%d movedIn=%d, want 1/2", movedOut, movedIn)
265		}
266	
267		// A live Reorg of this shape must report exactly the re-timed heights
268		// (h1's time is unchanged and is not reported), keep the tip at 5, and
269		// leave every hash/parent/tx list in place.
270		index := buildTwShiftOldChain(t)
271		dropped, err := index.Reorg(twShiftBranch())
272		if err != nil {
273			t.Fatalf("time-only reorg refused: %v", err)
274		}
275		if want := []int64{2, 3, 4, 5}; !reflect.DeepEqual(dropped, want) {
276			t.Fatalf("dropped=%v, want the four re-timed heights %v", dropped, want)
277		}
278		if index.Tip != 5 {
279			t.Fatalf("tip=%d, want unchanged 5", index.Tip)
280		}
281		for _, want := range newChain {
282			got, ok := index.Blocks[want.Height]
283			if !ok {
284				t.Fatalf("height %d missing after reorg", want.Height)
285			}
286			if !sameBlock(got, want) {
287				t.Fatalf("height %d stored block=%+v, want %+v", want.Height, got, want)
288			}
289			if index.ByHash[want.Hash] != want.Height {
290				t.Fatalf("hash %q resolves to %d, want %d", want.Hash, index.ByHash[want.Hash], want.Height)
291			}
292		}
293	}
294	
295	func sameIntptr(a, b *int64) bool {
296		if a == nil || b == nil {
297			return a == b
298		}
299		return *a == *b
300	}
301	
302	// The counting, ordering and window semantics the regression rests on,
303	// asserted on both chains and cross-checked against the live index before and
304	// after the time-only reorg.
305	func TestReorgTimeWindowQueryFixtureSemanticsOnBothChains(t *testing.T) {
306		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
307	
308		oldHits := twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
309		newHits := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
310		wantOld := []TxHit{
311			{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
312			{Height: 2, BlockHash: "h2", TxID: "m", Position: 0},
313			{Height: 2, BlockHash: "h2", TxID: "m", Position: 1},
314			{Height: 5, BlockHash: "h5", TxID: "m", Position: 0},
315			{Height: 5, BlockHash: "h5", TxID: "m", Position: 1},
316		}
317		wantNew := []TxHit{
318			{Height: 1, BlockHash: "h1", TxID: "m", Position: 0},
319			{Height: 3, BlockHash: "h3", TxID: "m", Position: 0},
320			{Height: 4, BlockHash: "h4", TxID: "m", Position: 0},
321			{Height: 5, BlockHash: "h5", TxID: "m", Position: 0},
322			{Height: 5, BlockHash: "h5", TxID: "m", Position: 1},
323		}
324		if !reflect.DeepEqual(oldHits, wantOld) {
325			t.Fatalf("old oracle hits=%v, want %v", oldHits, wantOld)
326		}
327		if !reflect.DeepEqual(newHits, wantNew) {
328			t.Fatalf("new oracle hits=%v, want %v", newHits, wantNew)
329		}
330		// Both chains hold five occurrences, but over a different number of blocks:
331		// this count divergence is what a same-total torn page cannot paper over.
332		if twReferenceMatchedBlocks(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd) != 3 {
333			t.Fatal("old chain must match 3 blocks (h1, h2, h5)")
334		}
335		if twReferenceMatchedBlocks(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd) != 4 {
336			t.Fatal("new chain must match 4 blocks (h1, h3, h4, h5)")
337		}
338		// Repeated identifiers inside one block keep their own positions and count
339		// separately; the non-matching companions x, z, q never leak through.
340		for _, gone := range []TxHit{
341			{Height: 2, BlockHash: "h2", TxID: "m", Position: 0},
342			{Height: 2, BlockHash: "h2", TxID: "m", Position: 1},
343		} {
344			if containsHit(newHits, gone) {
345				t.Fatalf("old-time occurrence %+v must leave the window", gone)
346			}
347		}
348		for _, entered := range []TxHit{
349			{Height: 3, BlockHash: "h3", TxID: "m", Position: 0},
350			{Height: 4, BlockHash: "h4", TxID: "m", Position: 0},
351		} {
352			if !containsHit(newHits, entered) {
353				t.Fatalf("new-time occurrence %+v must enter the window: %v", entered, newHits)
354			}
355		}
356		// Timestamps are not monotonic with height (h3 at 110 sits below h2 at
357		// 105/120, h5 dips to 102 after h4's 105), yet both answers stay in
358		// height/position order — never timestamp order.
359		requireOrdered(t, oldHits)
360		requireOrdered(t, newHits)
361	
362		// The oracle must match the live index on both complete chain states.
363		index := buildTwShiftOldChain(t)
364		live, err := index.QueryTxs(twShiftQuery())
365		if err != nil {
366			t.Fatal(err)
367		}
368		if !reflect.DeepEqual(viewOf(live), viewOf(twReferencePage(oldChain, twShiftPageSize, 0))) {
369			t.Fatalf("live old-chain page=%+v", live)
370		}
371		if !reflect.DeepEqual(live.Hits, literalTwShiftOldFirstPage().Hits) {
372			t.Fatalf("live old first page hits=%v, want literal %v", live.Hits, literalTwShiftOldFirstPage().Hits)
373		}
374	
375		if _, err := index.Reorg(twShiftBranch()); err != nil {
376			t.Fatalf("time-only reorg refused: %v", err)
377		}
378		live, err = index.QueryTxs(twShiftQuery())
379		if err != nil {
380			t.Fatal(err)
381		}
382		if !reflect.DeepEqual(viewOf(live), viewOf(twReferencePage(newChain, twShiftPageSize, 0))) {
383			t.Fatalf("live new-chain page=%+v", live)
384		}
385		if !reflect.DeepEqual(live.Hits, literalTwShiftNewFirstPage().Hits) {
386			t.Fatalf("live new first page hits=%v, want literal %v", live.Hits, literalTwShiftNewFirstPage().Hits)
387		}
388	
389		// On the OLD chain, starting the window exactly at zero still rejects the
390		// missing timestamp: widening the end to 200 admits every block carrying a
391		// value (including the real-zero h1 and the 110 h3) but never the nil h4.
392		oldIndex := buildTwShiftOldChain(t)
393		wide, err := oldIndex.QueryTxs(TxQuery{
394			TxIDs: []string{"m"}, TimeStart: intptr(0), TimeEnd: intptr(200),
395		})
396		if err != nil {
397			t.Fatal(err)
398		}
399		wideHeights := map[int64]bool{}
400		for _, h := range wide.Hits {
401			wideHeights[h.Height] = true
402		}
403		if !reflect.DeepEqual(wideHeights, map[int64]bool{1: true, 2: true, 3: true, 5: true}) {
404			t.Fatalf("old chain [0,200) matched heights %v, want every valued block 1,2,3,5 and not the nil h4", wideHeights)
405		}
406		if wide.TotalMatches != 6 || wide.MatchedBlocks != 4 {
407			t.Fatalf("old chain [0,200) stats=%+v, want 6 occurrences over 4 blocks", wide)
408		}
409	
410		// The half-open boundary and the real-zero/missing distinction are pinned
411		// on the new chain as well: the included zero keeps h1, a positive start
412		// drops it, h3 at 100 is included by [100,101), and h4's 105 is the
413		// excluded end of [0,105).
414		for _, tc := range []struct {
415			name        string
416			start, end  int64
417			wantHeights []int64
418		}{
419			{"fixture window [0,110)", 0, 110, []int64{1, 3, 4, 5}},
420			{"positive start drops real zero", 1, 110, []int64{3, 4, 5}},
421			{"end excluded at 105", 0, 105, []int64{1, 3, 5}},
422			{"only the included 100", 100, 101, []int64{3}},
423			{"window around zero keeps just h1", 0, 1, []int64{1}},
424		} {
425			t.Run(tc.name, func(t *testing.T) {
426				page, err := index.QueryTxs(TxQuery{
427					TxIDs: []string{"m"}, TimeStart: intptr(tc.start), TimeEnd: intptr(tc.end),
428				})
429				if err != nil {
430					t.Fatal(err)
431				}
432				gotHeights := map[int64]bool{}
433				for _, h := range page.Hits {
434					gotHeights[h.Height] = true
435				}
436				want := map[int64]bool{}
437				for _, h := range tc.wantHeights {
438					want[h] = true
439				}
440				if !reflect.DeepEqual(gotHeights, want) {
441					t.Fatalf("window [%d,%d) matched heights %v, want %v; hits=%v",
442						tc.start, tc.end, gotHeights, want, page.Hits)
443				}
444			})
445		}
446	}
447	
448	// classifyTimeWindowTxPage accepts got only when its visible contents are the
449	// first-page view of exactly one chain state under the pinned window. The
450	// opaque cursor is excluded and validated separately by following it. Records
451	// are provenanced against the COMPLETE filtered occurrence lists, so a page
452	// that stitches old-time hits to new-time statistics is rejected as MIXED even
453	// though both chains report TotalMatches 5 and the same upper height 5.
454	func classifyTimeWindowTxPage(got, oldRef, newRef TxPage, oldAllHits, newAllHits []TxHit) error {
455		type view struct {
456			Hits          []TxHit
457			TotalMatches  int64
458			MatchedBlocks int64
459			ToHeight      int64
460		}
461		of := func(p TxPage) view {
462			return view{Hits: p.Hits, TotalMatches: p.TotalMatches, MatchedBlocks: p.MatchedBlocks, ToHeight: p.ToHeight}
463		}
464		g, o, n := of(got), of(oldRef), of(newRef)
465		if reflect.DeepEqual(g, o) || reflect.DeepEqual(g, n) {
466			return nil
467		}
468	
469		var report strings.Builder
470		fmt.Fprintln(&report, "time-windowed QueryTxs page does not match one complete main chain:")
471		tags := map[string]bool{}
472		tag := func(name string, gotV, oldV, newV any) {
473			matchesOld := reflect.DeepEqual(gotV, oldV)
474			matchesNew := reflect.DeepEqual(gotV, newV)
475			label := "neither"
476			switch {
477			case matchesOld && matchesNew:
478				label = "both"
479			case matchesOld:
480				label = "OLD"
481				tags["old"] = true
482			case matchesNew:
483				label = "NEW"
484				tags["new"] = true
485			}
486			fmt.Fprintf(&report, "  %-15s got=%v old=%v new=%v -> %s\n", name, gotV, oldV, newV, label)
487		}
488		tag("ToHeight", g.ToHeight, o.ToHeight, n.ToHeight)
489		tag("TotalMatches", g.TotalMatches, o.TotalMatches, n.TotalMatches)
490		tag("MatchedBlocks", g.MatchedBlocks, o.MatchedBlocks, n.MatchedBlocks)
491	
492		oldByKey, newByKey := map[TxHit]bool{}, map[TxHit]bool{}
493		for _, h := range oldAllHits {
494			oldByKey[h] = true
495		}
496		for _, h := range newAllHits {
497			newByKey[h] = true
498		}
499		var inOld, inNew, inNeither, onlyOld, onlyNew int
500		ordered := true
501		for i, h := range g.Hits {
502			co, cn := oldByKey[h], newByKey[h]
503			if co {
504				inOld++
505			}
506			if cn {
507				inNew++
508			}
509			if co && !cn {
510				onlyOld++
511			}
512			if cn && !co {
513				onlyNew++
514			}
515			if !co && !cn {
516				inNeither++
517			}
518			if i > 0 {
519				prev := g.Hits[i-1]
520				if h.Height < prev.Height || (h.Height == prev.Height && h.Position <= prev.Position) {
521					ordered = false
522				}
523			}
524			if h.Height > g.ToHeight {
525				fmt.Fprintf(&report, "  hit above pinned ToHeight %d: %+v\n", g.ToHeight, h)
526			}
527		}
528		fmt.Fprintf(&report, "  Hits provenance  on-old=%d on-new=%d only-old=%d only-new=%d on-neither=%d (ordered=%v)\n",
529			inOld, inNew, onlyOld, onlyNew, inNeither, ordered)
530		if onlyOld > 0 {
531			tags["old"] = true
532		}
533		if onlyNew > 0 {
534			tags["new"] = true
535		}
536		switch {
537		case tags["old"] && tags["new"]:
538			fmt.Fprintf(&report, "  => MIXED: records and statistics come from different timestamp states; one page must reflect a single main chain")
539		case inNeither > 0:
540			fmt.Fprintf(&report, "  => CORRUPT: records exist under neither timestamp state")
541		case !ordered:
542			fmt.Fprintf(&report, "  => CORRUPT: page is not in height/position order")
543		default:
544			fmt.Fprintf(&report, "  => CORRUPT: matches neither the old nor the new timestamp state")
545		}
546		return errors.New(report.String())
547	}
