549	// The classifier must accept both complete answers and reject the
550	// equal-total mixtures this reorg shape is prone to.
551	func TestClassifyTimeWindowTxPageRejectsStitchedPages(t *testing.T) {
552		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
553		oldRef := twReferencePage(oldChain, twShiftPageSize, 0)
554		newRef := twReferencePage(newChain, twShiftPageSize, 0)
555		oldAll := twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
556		newAll := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
557		classify := func(page TxPage) error { return classifyTimeWindowTxPage(page, oldRef, newRef, oldAll, newAll) }
558		if err := classify(oldRef); err != nil {
559			t.Fatalf("pure old page rejected: %v", err)
560		}
561		if err := classify(newRef); err != nil {
562			t.Fatalf("pure new page rejected: %v", err)
563		}
564	
565		// Mixture 1: old-time records, but new-time MatchedBlocks. TotalMatches is
566		// 5 on both chains, so a total-only consistency check would accept this.
567		mixed1 := oldRef
568		mixed1.MatchedBlocks = newRef.MatchedBlocks
569		if err := classify(mixed1); err == nil {
570			t.Fatal("old hits with new-time block count were accepted")
571		} else if !strings.Contains(err.Error(), "MIXED") {
572			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
573		}
574	
575		// Mixture 2: the exact torn answer the task names — records read under the
576		// old times, statistics counted under the new times — built by hand rather
577		// than borrowed from either reference page.
578		mixed2 := TxPage{
579			Hits: []TxHit{
580				{Height: 1, BlockHash: "h1", TxID: "m", Position: 0}, // shared
581				{Height: 2, BlockHash: "h2", TxID: "m", Position: 0}, // OLD only
582			},
583			TotalMatches:  5,
584			MatchedBlocks: 4, // NEW
585			ToHeight:      5,
586		}
587		if err := classify(mixed2); err == nil {
588			t.Fatal("stitched old-records/new-stats page was accepted")
589		} else if !strings.Contains(err.Error(), "MIXED") {
590			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
591		}
592	
593		// Mixture 3: new-time records carrying the old block count.
594		mixed3 := newRef
595		mixed3.MatchedBlocks = oldRef.MatchedBlocks
596		if err := classify(mixed3); err == nil {
597			t.Fatal("new hits with old-time block count were accepted")
598		} else if !strings.Contains(err.Error(), "MIXED") {
599			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
600		}
601	
602		// Corruption: a matched-block count that belongs to neither state.
603		corrupt := newRef
604		corrupt.MatchedBlocks = 99
605		if err := classify(corrupt); err == nil {
606			t.Fatal("corrupt stats matching neither state were accepted")
607		}
608	}
609	
610	// Ordering 1: the windowed first page is holding the lock on the complete OLD
611	// timestamp state (tip already pinned) when the time-only reorg starts and
612	// blocks on the lock. The page must finish entirely against the old times —
613	// literal h1/h2 records, 5 occurrences over 3 blocks, upper height 5 and a
614	// cursor pinned to the old fingerprint — and must not fail a valid first page.
615	// After the reorg commits, that cursor must die with a zeroed
616	// ErrQueryChanged: the records the new times filter in may not be appended
617	// after the old page.
618	func TestQueryTxsTimeWindowFirstPageInFlightObservesCompleteOldTimes(t *testing.T) {
619		index := buildTwShiftOldChain(t)
620		h := installQueryReorgHooks(t, true, false, 5)
621		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
622	
623		result := make(chan TxPage, 1)
624		errCh := make(chan error, 1)
625		go func() {
626			page, err := index.QueryTxs(twShiftQuery())
627			if err != nil {
628				errCh <- err
629				return
630			}
631			result <- page
632		}()
633	
634		<-h.firstParked // first page holds index.mu and has pinned the old state
635		reorgDone := make(chan struct{})
636		go func() {
637			if _, err := index.Reorg(twShiftBranch()); err != nil {
638				errCh <- err
639			}
640			close(reorgDone)
641		}()
642	
643		close(h.releaseFirst) // the page scans and finishes against the old times
644		var got TxPage
645		select {
646		case got = <-result:
647		case err := <-errCh:
648			t.Fatalf("concurrent first page failed: %v", err)
649		}
650		want := twReferencePage(oldChain, twShiftPageSize, 0)
651		if err := classifyTimeWindowTxPage(got, want, twReferencePage(newChain, twShiftPageSize, 0),
652			twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd),
653			twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)); err != nil {
654			t.Fatalf("in-flight first page did not return one complete chain state:\n%v", err)
655		}
656		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
657			t.Fatalf("page holding the lock across reorg start must see the old times:\n%+v", got)
658		}
659		if !reflect.DeepEqual(got.Hits, literalTwShiftOldFirstPage().Hits) {
660			t.Fatalf("old first page hits=%v, want literal h1/h2 records", got.Hits)
661		}
662		if got.NextCursor == "" {
663			t.Fatal("old first page over 5 matches (page size 2) must carry a cursor")
664		}
665	
666		close(h.releaseReorg) // let the time-only reorg commit and return
667		<-reorgDone
668		if index.Tip != 5 {
669			t.Fatalf("tip after time-only reorg=%d, want 5", index.Tip)
670		}
671	
672		// The cursor pins the OLD timestamp state even though the height span,
673		// hashes, parent links and transaction lists are all unchanged: only the
674		// timestamp bytes in the fingerprint differ.
675		oldFingerprint := buildTwShiftOldChain(t)
676		payload := decodePayload(t, index, got.NextCursor)
677		if payload.To != 5 || payload.Off != 2 {
678			t.Fatalf("cursor pins to=%d off=%d, want 5/2", payload.To, payload.Off)
679		}
680		if payload.window() != (timeWindow{enabled: true, start: twShiftWindowStart, end: twShiftWindowEnd}) {
681			t.Fatalf("cursor window=%+v, want the pinned [0,110)", payload.window())
682		}
683		if payload.FP != fmt.Sprintf("%x", oldFingerprint.fingerprintLocked(1, 5)) {
684			t.Fatal("cursor fingerprint does not match the complete OLD timestamp state")
685		}
686	
687		// Continuing the old cursor on the new state must fail closed: no hits, no
688		// replacement cursor, no usable statistics — the h3/h4 records the new
689		// times filter in must never be stitched behind the h1/h2 old page.
690		page, err := index.QueryTxs(func() TxQuery {
691			q := twShiftQuery()
692			q.Cursor = got.NextCursor
693			return q
694		}())
695		if !errors.Is(err, ErrQueryChanged) {
696			t.Fatalf("old cursor across time-only reorg: err=%v page=%+v, want ErrQueryChanged", err, page)
697		}
698		if errors.Is(err, ErrInvalidArgument) {
699			t.Fatalf("a committed reorg must not be reported as an argument error: %v", err)
700		}
701		if !reflect.DeepEqual(page, TxPage{}) {
702			t.Fatalf("changed continuation must return a fully zeroed page, got %+v", page)
703		}
704	}
705	
706	// Ordering 2: the time-only reorg has fully committed (new timestamps live,
707	// Reorg still holding the lock) when the first page starts. It waits, then
708	// answers entirely against the NEW times — literal h1/h3 records, 5
709	// occurrences over 4 blocks, upper height 5 — and its cursor must drain the
710	// new state to the end with no duplicate or missing occurrence, identical
711	// statistics on every page, and no cursor once the last match is returned.
712	func TestQueryTxsTimeWindowFirstPageDuringCommittedReorgObservesCompleteNewTimes(t *testing.T) {
713		index := buildTwShiftOldChain(t)
714		h := installQueryReorgHooks(t, true, false, 5)
715		oldChain, newChain := twShiftOldChain(), twShiftNewChain()
716	
717		reorgErr := make(chan error, 1)
718		go func() {
719			_, err := index.Reorg(twShiftBranch())
720			reorgErr <- err
721		}()
722		<-h.reorgParked // new timestamps applied (tip still 5), Reorg holds the lock
723	
724		result := make(chan TxPage, 1)
725		errCh := make(chan error, 1)
726		go func() {
727			page, err := index.QueryTxs(twShiftQuery())
728			if err != nil {
729				errCh <- err
730				return
731			}
732			result <- page
733		}()
734	
735		close(h.releaseReorg) // Reorg returns; the first lock the page can get is the new state
736		if err := <-reorgErr; err != nil {
737			t.Fatalf("time-only reorg failed: %v", err)
738		}
739		close(h.releaseFirst) // the parked first page can now scan and finish
740	
741		var got TxPage
742		select {
743		case got = <-result:
744		case err := <-errCh:
745			t.Fatalf("first page during committed reorg must not fail: %v", err)
746		}
747		want := twReferencePage(newChain, twShiftPageSize, 0)
748		if err := classifyTimeWindowTxPage(got, twReferencePage(oldChain, twShiftPageSize, 0), want,
749			twReferenceHits(oldChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd),
750			twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)); err != nil {
751			t.Fatalf("first page across reorg commit did not return one complete chain state:\n%v", err)
752		}
753		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
754			t.Fatalf("page after reorg commit must see the complete new times:\n%+v", got)
755		}
756		if !reflect.DeepEqual(got.Hits, literalTwShiftNewFirstPage().Hits) {
757			t.Fatalf("new first page hits=%v, want literal h1/h3 records", got.Hits)
758		}
759		if got.NextCursor == "" {
760			t.Fatal("new first page over 5 matches (page size 2) must carry a cursor")
761		}
762		for _, hit := range got.Hits {
763			if hit.Height == 2 {
764				t.Fatalf("old-time h2 occurrence must not appear under the new times: %+v", hit)
765			}
766		}
767	
768		// The cursor pins the NEW timestamp state.
769		newFingerprint := New()
770		for _, b := range newChain {
771			if err := newFingerprint.Append(b); err != nil {
772				t.Fatal(err)
773			}
774		}
775		payload := decodePayload(t, index, got.NextCursor)
776		if payload.To != 5 || payload.Off != 2 {
777			t.Fatalf("cursor pins to=%d off=%d, want 5/2", payload.To, payload.Off)
778		}
779		if payload.FP != fmt.Sprintf("%x", newFingerprint.fingerprintLocked(1, 5)) {
780			t.Fatal("cursor fingerprint does not match the complete NEW timestamp state")
781		}
782	
783		// Drain the cursor while the chain stays put: every match of the new state
784		// exactly once, statistics fixed at 5/4/upper-5 on every page, and the
785		// cursor chain ends after the fifth occurrence.
786		query := twShiftQuery()
787		query.Cursor = got.NextCursor
788		all := append([]TxHit{}, got.Hits...)
789		pageCount := 1
790		for {
791			page, err := index.QueryTxs(query)
792			if err != nil {
793				t.Fatalf("new-state continuation failed at page %d: %v", pageCount+1, err)
794			}
795			if page.TotalMatches != 5 || page.MatchedBlocks != 4 || page.ToHeight != 5 {
796				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageCount+1, page)
797			}
798			all = append(all, page.Hits...)
799			pageCount++
800			if page.NextCursor == "" {
801				break
802			}
803			query.Cursor = page.NextCursor
804		}
805		wantAll := twReferenceHits(newChain, []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
806		if !reflect.DeepEqual(all, wantAll) {
807			t.Fatalf("new-state pagination duplicated or lost occurrences:\n got=%v\nwant=%v", all, wantAll)
808		}
809		if pageCount != 3 {
810			t.Fatalf("pages=%d, want 3 (2/2/1 over five hits)", pageCount)
811		}
812	}
813	
814	// A cursor minted against the old state must keep working only while the
815	// timestamp state is untouched; once any pinned height is re-timed — even a
816	// block the window excluded (h3 at 110) or one with a missing timestamp (h4) —
817	// the continuation fails closed with a zeroed page. Repeating the exact old
818	// branch is a no-op-style reorg that leaves the cursor valid.
819	func TestQueryTxsTimeWindowCursorDiesOnAnyPinnedTimestampMove(t *testing.T) {
820		sameAsOld := twShiftOldChain()[1:] // heights 2..5 verbatim, including times
821	
822		t.Run("re-timing an excluded-end block kills the cursor", func(t *testing.T) {
823			index := buildTwShiftOldChain(t)
824			first, err := index.QueryTxs(twShiftQuery())
825			if err != nil {
826				t.Fatal(err)
827			}
828			// Move only h3 (110 -> 105): the tip stays 5 and the other three
829			// blocks are byte-identical, yet the range fingerprint changes.
830			branch := []Block{
831				twShiftBlock(2, "h2", "h1", []string{"m", "m"}, intptr(105)),
832				twShiftBlock(3, "h3", "h2", []string{"m", "z"}, intptr(105)),
833				twShiftBlock(4, "h4", "h3", []string{"m", "q"}, nil),
834				twShiftBlock(5, "h5", "h4", []string{"m", "m"}, intptr(108)),
835			}
836			if _, err := index.Reorg(branch); err != nil {
837				t.Fatal(err)
838			}
839			if index.Tip != 5 {
840				t.Fatalf("tip=%d, want the unchanged tip 5", index.Tip)
841			}
842			query := twShiftQuery()
843			query.Cursor = first.NextCursor
844			page, err := index.QueryTxs(query)
845			requireChangedZeroed(t, page, err)
846		})
847	
848		t.Run("giving a missing timestamp a value kills the cursor", func(t *testing.T) {
849			index := buildTwShiftOldChain(t)
850			first, err := index.QueryTxs(twShiftQuery())
851			if err != nil {
852				t.Fatal(err)
853			}
854			// Only h4 changes: nil -> 105 (it additionally enters the window).
855			branch := []Block{
856				twShiftBlock(2, "h2", "h1", []string{"m", "m"}, intptr(105)),
857				twShiftBlock(3, "h3", "h2", []string{"m", "z"}, intptr(110)),
858				twShiftBlock(4, "h4", "h3", []string{"m", "q"}, intptr(105)),
859				twShiftBlock(5, "h5", "h4", []string{"m", "m"}, intptr(108)),
860			}
861			if _, err := index.Reorg(branch); err != nil {
862				t.Fatal(err)
863			}
864			query := twShiftQuery()
865			query.Cursor = first.NextCursor
866			page, err := index.QueryTxs(query)
867			requireChangedZeroed(t, page, err)
868		})
869	
870		t.Run("identical branch keeps the cursor alive", func(t *testing.T) {
871			index := buildTwShiftOldChain(t)
872			pages := collectPages(t, index, twShiftQuery())
873			cursor := pages[0].NextCursor
874			dropped, err := index.Reorg(sameAsOld)
875			if err != nil {
876				t.Fatal(err)
877			}
878			if len(dropped) != 0 {
879				t.Fatalf("re-submitting the identical branch dropped=%v, want none", dropped)
880			}
881			query := twShiftQuery()
882			query.Cursor = cursor
883			page, err := index.QueryTxs(query)
884			if err != nil {
885				t.Fatalf("cursor must survive an identical-branch reorg: %v", err)
886			}
887			if page.TotalMatches != 5 || page.MatchedBlocks != 3 || page.ToHeight != 5 {
888				t.Fatalf("statistics drifted: %+v", page)
889			}
890		})
891	}
892	
893	// Timing-independent overlap: reorgers alternate between the old and the new
894	// timestamp states while windowed readers paginate continuously, with no
895	// rendezvous hooks. The fixed tip and equal totals make this the dangerous
896	// case for a torn answer; every first page must classify as exactly one
897	// timestamp state, and every continuation must either keep draining that exact
898	// state or fail with a zeroed ErrQueryChanged.
899	func TestQueryTxsRepeatedTimeOnlyReorgsStayConsistent(t *testing.T) {
900		index := buildTwShiftOldChain(t)
901		oldAll := twReferenceHits(twShiftOldChain(), []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
902		newAll := twReferenceHits(twShiftNewChain(), []string{"m"}, twShiftWindowStart, twShiftWindowEnd)
903		oldBranch := twShiftOldChain()[1:]
904		newBranch := twShiftBranch()
905	
906		const pageSize = twShiftPageSize
907		const reorgers = 2
908		const rounds = 40
909		const readers = 4
910		const runs = 60
911	
912		stop := make(chan struct{})
913		var wg sync.WaitGroup
914		for r := 0; r < reorgers; r++ {
915			wg.Add(1)
916			go func(seed int) {
917				defer wg.Done()
918				for i := 0; i < rounds; i++ {
919					select {
920					case <-stop:
921						return
922					default:
923					}
924					branch := newBranch
925					if (i+seed)%2 == 0 {
926						branch = oldBranch
927					}
928					if _, err := index.Reorg(branch); err != nil {
929						t.Errorf("time-only reorg failed: %v", err)
930						return
931					}
932				}
933			}(r)
934		}
935	
936		for r := 0; r < readers; r++ {
937			wg.Add(1)
938			go func() {
939				defer wg.Done()
940				for run := 0; run < runs; run++ {
941					select {
942					case <-stop:
943						return
944					default:
945					}
946					first, err := index.QueryTxs(twShiftQuery())
947					if err != nil {
948						t.Errorf("first page failed: %v", err)
949						return
950					}
951					// Tip 5 and TotalMatches 5 on both states: only the records and
952					// MatchedBlocks distinguish them, which is exactly why the
953					// full classifier (not a count check) must be used.
954					var stateHits []TxHit
955					switch first.MatchedBlocks {
956					case 3:
957						stateHits = oldAll
958					case 4:
959						stateHits = newAll
960					default:
961						t.Errorf("first page matched-blocks=%d, want 3 (old) or 4 (new)", first.MatchedBlocks)
962						return
963					}
964					if first.ToHeight != 5 || first.TotalMatches != 5 {
965						t.Errorf("first page stats=%+v, want total 5 upper 5", first)
966						return
967					}
968					if err := classifyTimeWindowTxPage(first,
969						twReferencePage(twShiftOldChain(), pageSize, 0),
970						twReferencePage(twShiftNewChain(), pageSize, 0),
971						oldAll, newAll); err != nil {
972						t.Errorf("%v", err)
973						return
974					}
975					seen := append([]TxHit{}, first.Hits...)
976					if !reflect.DeepEqual(first.Hits, stateHits[:len(first.Hits)]) {
977						t.Errorf("first page records do not match its timestamp state:\n%+v", first.Hits)
978						return
979					}
980					query := twShiftQuery()
981					query.Cursor = first.NextCursor
982					for query.Cursor != "" {
983						page, err := index.QueryTxs(query)
984						if errors.Is(err, ErrQueryChanged) {
985							if !reflect.DeepEqual(page, TxPage{}) {
986								t.Errorf("changed continuation leaked %+v", page)
987							}
988							break // the pinned timestamp state moved; restart fresh
989						}
990						if err != nil {
991							t.Errorf("continuation failed: %v", err)
992							return
993						}
994						if page.TotalMatches != first.TotalMatches || page.ToHeight != first.ToHeight {
995							t.Errorf("statistics drifted mid-pagination: %+v", page)
996							return
997						}
998						if page.MatchedBlocks != first.MatchedBlocks {
999							t.Errorf("matched-block count changed from %d to %d mid-pagination",
1000								first.MatchedBlocks, page.MatchedBlocks)
1001							return
1002						}
1003						wantSlice := stateHits[len(seen):]
1004						if len(wantSlice) > pageSize {
1005							wantSlice = wantSlice[:pageSize]
1006						}
1007						if !reflect.DeepEqual(page.Hits, wantSlice) {
1008							t.Errorf("continuation records do not match the pinned state:\n%+v", page.Hits)
1009							return
1010						}
1011						seen = append(seen, page.Hits...)
1012						query.Cursor = page.NextCursor
1013						if query.Cursor == "" && len(seen) != len(stateHits) {
1014							t.Errorf("cursor chain ended after %d hits, state has %d", len(seen), len(stateHits))
1015							return
1016						}
1017					}
1018				}
1019			}()
1020		}
1021	
1022		wg.Wait()
1023		close(stop)
1024	
1025		// Leave the index deterministically on the new timestamp state and read it
1026		// to the end against the oracle.
1027		if _, err := index.Reorg(newBranch); err != nil {
1028			t.Fatalf("final reorg failed: %v", err)
1029		}
1030		pages := collectPages(t, index, twShiftQuery())
1031		var all []TxHit
1032		for _, page := range pages {
1033			if page.TotalMatches != 5 || page.MatchedBlocks != 4 || page.ToHeight != 5 {
1034				t.Fatalf("final pagination stats drifted: %+v", page)
1035			}
1036			all = append(all, page.Hits...)
1037		}
1038		if !reflect.DeepEqual(all, newAll) {
1039			t.Fatalf("final new-state pagination=%v, want %v", all, newAll)
1040		}
1041	}
